            except Exception as e:
                sys.stderr.write(f"error: cannot open {fname}: {e}\n")
                sys.exit(2)
    else:
        # read stdin
        data = sys.stdin.read()
        if data == '' and sys.stdin.isatty():
            # no stdin and no files: treat as null? jq would wait; but we'll exit
            data = ''
        if opts['raw_input']:
            for line in data.splitlines():
                docs.append(line)
        else:
            if data.strip() == '':
                # empty input
                return []
            try:
                docs.append(json.loads(data))
            except Exception:
                # try to parse multiple JSON texts in input by searching positions
                # naive: split by newline and parse each non-empty
                for line in data.splitlines():
                    if line.strip() == '': continue
                    try:
                        docs.append(json.loads(line))
                    except Exception:
                        # as fallback, try eval to null
                        pass
    return docs


def apply_filter(value, filter_expr, args_positional=None):
    # support only '.' and '.key' and chained and array index like .foo[0]
    if filter_expr is None:
        # jq default filter is .
        filter_expr='.'
    f = filter_expr.strip()
    if f == '.':
        return value
    # support filters like .foo.bar
    if f.startswith('.'):
        cur = value
        path = f[1:]
        # split by . but keep [] accesses
        # parse sequence of parts
        parts = re.findall(r"[^.\[\]]+|\[\d+\]", path)
        try:
            for p in parts:
                if p.startswith('[') and p.endswith(']'):
                    idx = int(p[1:-1])
                    if isinstance(cur, list):
                        cur = cur[idx]
                    else:
                        raise Exception('not an array')
                else:
                    if cur is None:
                        cur = None
                    elif isinstance(cur, dict):
                        cur = cur.get(p)
                    else:
                        # cannot get attribute
                        cur = None
            return cur
        except Exception:
            return None
    # unsupported: try to eval as literal
    return None


def output_value(val, opts):
    out = ''
    is_raw = opts['raw_output'] or opts['raw_output0'] or opts['join_output']
    if is_raw and isinstance(val, str):
        out = val
    else:
        if opts['compact']:
            out = json.dumps(val, separators=(',',':'))
        else:
            out = json.dumps(val, indent=2, ensure_ascii=False)
    if opts['raw_output0']:
        end = '\0'
    elif opts['join_output']:
        end = ''
    else:
        end = '\n'
    return out + end


def main():
    opts, filter_arg, rest, consume_as = parse_args(sys.argv)
    if consume_as=='args':
        # not implemented: just exit
        pos = rest
        # output nothing
        sys.exit(0)
    if consume_as=='jsonargs':
        sys.exit(0)
    docs = read_inputs(rest, opts)
    if not docs and not opts['null_input']:
        # nothing to do
        return
    if opts['slurp']:
        input_value = docs
        res = apply_filter(input_value, filter_arg)
        if res is None:
            # print null
            res = None
        sys.stdout.write(output_value(res, opts))
        return
    # apply filter to each doc and print
    first = True
    outbuf = []
    for d in docs:
        res = apply_filter(d, filter_arg)
        if res is None:
            # jq prints null for None values
            # But if result is None because key absent, jq prints null
            pass
        out = output_value(res, opts)
        sys.stdout.write(out)
    # flush

if __name__=='__main__':
    main()
